from typing import Any, Dict, List, Union


class OCRRequest:
    def __init__(self, image_path: str, language: str = 'eng'):
        self.image_path = image_path
        self.language = language


class OCRResponse:
    def __init__(self, text: str, confidence: float):
        self.text = text
        self.confidence = confidence


class LayoutExtractionRequest:
    def __init__(self, image_path: str):
        self.image_path = image_path


class LayoutExtractionResponse:
    def __init__(self, layout: Dict[str, Any]):
        self.layout = layout


def normalize_ocr_text(text: str) -> str:
    return text.strip().replace('\n', ' ').replace('  ', ' ')


def normalize_layout(layout: Dict[str, Any]) -> Dict[str, Any]:
    normalized_layout = {}
    for key, value in layout.items():
        if isinstance(value, str):
            normalized_layout[key] = value.strip()
        elif isinstance(value, list):
            normalized_layout[key] = [item.strip() for item in value]
        else:
            normalized_layout[key] = value
    return normalized_layout

import boto3

def get_textract_client():
    return boto3.client('textract')

def ocr_layout_extraction(document):
    client = get_textract_client()
    response = client.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['TABLES', 'FORMS'])
    return response

import boto3

def extract_key_values(document_path):
    textract_client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        image_bytes = document.read()
    response = textract_client.analyze_document(
        Document={'Bytes': image_bytes},
        FeatureTypes=['FORMS'])
    key_value_pairs = {}
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_PAIR':
            key = next((child['Text'] for child in block['Relationships'] if child['Type'] == 'CHILD' and child['Block']['BlockType'] == 'WORD'), None)
            value = next((child['Text'] for child in block['Relationships'] if child['Type'] == 'VALUE' and child['Block']['BlockType'] == 'WORD'), None)
            if key and value:
                key_value_pairs[key] = value
    return key_value_pairs

import boto3

def extract_tables(document_path):
    textract_client = boto3.client('textract')
    with open(document_path, 'rb') as document:
        document_bytes = document.read()
    response = textract_client.analyze_document(
        Document={'Bytes': document_bytes},
        FeatureTypes=['TABLES'])
    tables = []
    for table in response['Blocks']:
        if table['BlockType'] == 'TABLE':
            table_cells = []
            for relationship in table['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        for block in response['Blocks']:
                            if block['Id'] == child_id:
                                if block['BlockType'] == 'CELL':
                                    table_cells.append(block['Text'])
            tables.append(table_cells)
    return tables

if __name__ == '__main__':
    document_path = 'sample_document.pdf'
    tables = extract_tables(document_path)
    for table in tables:
        print(table)
